using System;using System.Runtime.CompilerServices;using Unity.Entities;using Game.Components;using Game.Configs;
namespace Game.Runtime{internal static class SourceNativeDeathBinding{
 static readonly ConditionalWeakTable<EntityManager,SourceNativeDeathReadModel> contexts=new ConditionalWeakTable<EntityManager,SourceNativeDeathReadModel>();
 internal static void BindAtBoundary(EntityManager manager,SourceNativeDeathReadModel model){if(manager==null||model==null)throw new ArgumentNullException();contexts.Add(manager,model);UnitDeathAnimationPlaybackUtility.QualifiedHeadlessClipReader=TryRead;}
 internal static EntityQueryDesc UnitAuthoringPreflightQuery()=>new EntityQueryDesc{All=new[]{ComponentType.ReadOnly<UnitHealth>(),ComponentType.ReadOnly<UnitAnimationSettings>(),ComponentType.ReadOnly<SkirmishUnitRoleComponent>()},None=new[]{ComponentType.ReadOnly<StaticGridBlocker>()}};
 internal static void ValidateActualUnits(EntityManager manager){if(!contexts.TryGetValue(manager,out var model))throw new NotSupportedException("Mandatory native death input model not bound");using var query=manager.CreateEntityQuery(UnitAuthoringPreflightQuery());using var units=query.ToEntityArray(Unity.Collections.Allocator.Temp);foreach(var unit in units){if(!manager.HasComponent<UnitSourcePrefabKey>(unit))throw new NotSupportedException("Actual death candidate missing source prefab identity");string key=manager.GetComponentData<UnitSourcePrefabKey>(unit).Value.ToString();float configured=manager.GetComponentData<UnitAnimationSettings>(unit).DeathAnimationSeconds;bool selected=UnitDeathAnimationPlaybackUtility.ResolveActualDeathIndex(manager,unit,out byte index);var row=model.Require(key,BitConverter.ToUInt32(BitConverter.GetBytes(configured),0),index);bool configuredWreck=manager.HasComponent<VehicleDestroyedVisualPrefabReference>(unit)&&manager.Exists(manager.GetComponentData<VehicleDestroyedVisualPrefabReference>(unit).Prefab);bool legacy=manager.HasComponent<UnitDestroyedVisualReference>(unit);if(selected!=row.HasSelection||configuredWreck!=row.ConfiguredWreck||legacy!=row.LegacyWreck)throw new NotSupportedException("Actual original death selection/wreck bypass changed");}}
 static bool TryRead(EntityManager manager,Entity unit,float configured,byte deathIndex,out UnitDeathMechanicalClipInput[][] inputs){inputs=null;if(!contexts.TryGetValue(manager,out var model))return false;if(!manager.Exists(unit)||!manager.HasComponent<UnitSourcePrefabKey>(unit))throw new NotSupportedException("Qualified native death reader requires actual prefab identity");string key=manager.GetComponentData<UnitSourcePrefabKey>(unit).Value.ToString();uint bits=BitConverter.ToUInt32(BitConverter.GetBytes(configured),0);var row=model.Require(key,bits,deathIndex);if(!row.HasSelection||row.ConfiguredWreck||row.LegacyWreck)throw new NotSupportedException("Original wreck/no-selection bypass must precede headless clip preparation");inputs=row.Inputs;return true;}
}}
